/**
 * ۱۷. به سوی فانوس دریایی — ویرجینیا وولف
 */
object Story17 {

    fun get(): StoryContent = StoryContent(
        storyId = "adv_to_the_lighthouse",
        chapters = listOf(
            chapter1(),
            chapter2(),
            chapter3(),
            chapter4(),
            chapter5(),
            chapter6(),
        )
    )

    // ─────────── فصل ۱: پنجره ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Window", titlePersian = "پنجره",
        paragraphs = listOf(
            StoryParagraph("'Yes, of course, if it's fine tomorrow,' said Mrs. Ramsay. 'But you'll have to be up with the lark,' she added.", "خانم رامزی گفت: «بله، البته، اگر فردا هوا خوب باشد. اما باید سحرخیز باشی.»"),
            StoryParagraph("To her son these words conveyed an extraordinary joy, as if it were settled, the expedition were bound to take place.", "برای پسرش این کلمات شادی فوق‌العاده‌ای منتقل می‌کرد، گویی قطعی شده بود، سفر حتماً انجام می‌شد."),
            StoryParagraph("Since he was two years old, and even now, at six, he had always cherished the same hope of going to the Lighthouse.", "از دو سالگی و حتی حالا در شش سالگی، همیشه همین امید رفتن به فانوس دریایی را در دل داشت."),
            StoryParagraph("James Ramsay, sitting on the floor cutting out pictures from an illustrated catalogue, felt the joy rise in his heart.", "جیمز رامزی که روی زمین نشسته بود و از کاتالوگی مصور تصاویر می‌برید، شادی را در قلبش بالا رفتن حس کرد."),
            StoryParagraph("But at that moment, his father, who was passing the window, stopped and said, 'It won't be fine.'", "اما در همان لحظه، پدرش که از کنار پنجره می‌گذشت ایستاد و گفت: «هوا خوب نخواهد بود.»"),
            StoryParagraph("'But it's almost certain to be fine tomorrow,' Mrs. Ramsay said, defending the expedition, defending her son's hope.", "خانم رامزی گفت: «اما تقریباً قطعی است که فردا هوا خوب باشد.» از سفر دفاع می‌کرد، از امید پسرش."),
            StoryParagraph("'Damn you,' said Mr. Ramsay, striding past. 'The wind is west, and it's raining.'", "آقای رامزی در حالی که می‌گذشت گفت: «لعنت به تو. باد غربی است و باران می‌آید.»"),
            StoryParagraph("James, at the mere sound of his father's voice, felt the bitterness of disappointment settle in his heart like a stone.", "جیمز با شنیدن صدای پدرش، تلخی ناامیدی را مثل سنگی در قلبش نشستن حس کرد."),
            StoryParagraph("To his mind there was no doubt at all that his father was right; he always was right; he always knew what the weather would do.", "در ذهنش هیچ شکی نبود که پدرش حق دارد؛ همیشه حق داشت؛ همیشه می‌دانست هوا چه می‌کند."),
            StoryParagraph("And James hated him for it — hated him with a passion that would last a lifetime.", "و جیمز برای این از او متنفر بود — با شوری متنفر بود که یک عمر دوام می‌آورد."),
            StoryParagraph("The window of the Ramsays' summer house was open to the lawn, and beyond the lawn, to the sea.", "پنجره خانه تابستانی رامزی‌ها به چمن باز بود و آنسوی چمن، به دریا."),
            StoryParagraph("Out in the bay, a mile or so away, the Lighthouse stood, a stark white tower on a barren rock, and it was toward this tower that James had dreamed of sailing for as long as he could remember.", "در خلیج، حدود یک مایل دورتر، فانوس دریایی ایستاده بود، برجی سفید و لخت روی صخره‌ای بایر و این برج بود که جیمز تا آنجا که به یاد داشت آرزوی دریانوردی به سمتش را داشت."),
            StoryParagraph("Mrs. Ramsay, sitting by the window, watched her son, and she felt his pain, and she pitied him.", "خانم رامزی که کنار پنجره نشسته بود پسرش را تماشا کرد و دردش را حس کرد و برایش ترحم کرد."),
            StoryParagraph("She was a woman of extraordinary beauty, even at fifty, with hair that had once been black and was now silver, and with eyes that seemed to see everything.", "زنی با زیبایی فوق‌العاده بود، حتی در پنجاه سالگی، با موهایی که روزی سیاه بوده و حالا نقره‌ای بود و با چشمانی که به نظر می‌رسید همه چیز را می‌بینند."),
            StoryParagraph("But more than her beauty, it was her warmth, her sympathy, her capacity to feel with others, that drew people to her.", "اما بیش از زیبایی‌اش، گرمی‌اش بود، همدلی‌اش، ظرفیتش برای حس کردن با دیگران، که مردم را جذبش می‌کرد."),
            StoryParagraph("Her husband, Mr. Ramsay, was a philosopher, a man of great reputation and greater self-doubt.", "شوهرش، آقای رامزی، فیلسوف بود، مردی با شهرت فراوان و شک بیشتر به خودش."),
            StoryParagraph("He had written books that were admired; he had achieved success that others envied; and yet he was never satisfied.", "کتاب‌هایی نوشته بود که تحسین می‌شد؛ موفقیتی کسب کرده بود که دیگران حسرتش را می‌خوردند؛ و با این حال هرگز راضی نبود."),
            StoryParagraph("He thought always of the great work he had not yet done, of the peak he had not yet climbed, of the letter that came after Q.", "همیشه به کار بزرگی که هنوز نکرده بود فکر می‌کرد، به قلتی که هنوز بالا نرفته بود، به حرفی که پس از Q می‌آید."),
            StoryParagraph("'It won't be fine,' he had said, and he had said it because he could not bear to see his son happy.", "گفته بود: «هوا خوب نخواهد بود.» و گفته بود چون نمی‌توانست ببیند پسرش خوشحال است."),
            StoryParagraph("Or rather, he could not bear to see his son's happiness depend on a hope that might be disappointed, and so he had destroyed the hope before it could be destroyed by the world.", "یا بهتر، نمی‌توانست ببیند شادی پسرش به امیدی وابسته است که ممکن بود ناامید شود و بنابراین امید را نابود کرده بود پیش از آنکه توسط جهان نابود شود."),
            StoryParagraph("This was Mr. Ramsay: brilliant, insecure, tyrannical, pitiable — a man who needed love and could not ask for it.", "این آقای رامزی بود: درخشان، ناایمن، مستبد، رقت‌انگیز — مردی که به عشق نیاز داشت و نمی‌توانست درخواستش کند."),
            StoryParagraph("Outside, on the lawn, a young woman named Lily Briscoe was painting.", "بیرون، روی چمن، زن جوانی به نام لیلی بریسکو نقاشی می‌کرد."),
            StoryParagraph("She was not beautiful, and she knew it; and she did not care, or told herself she did not care.", "زیبا نبود و می‌دانست؛ و اهمیتی نمی‌داد، یا به خودش می‌گفت اهمیتی نمی‌دهم."),
            StoryParagraph("What she cared about was her painting; she was trying to capture something, something about Mrs. Ramsay and James at the window.", "چیزی که اهمیت می‌داد نقاشی‌اش بود؛ تلاش می‌کرد چیزی را ثبت کند، چیزی درباره خانم رامزی و جیمز در پنجره."),
            StoryParagraph("She had been painting for years, and she had never quite succeeded; she had never quite found the shape, the form, the meaning.", "سال‌ها نقاشی کرده بود و هرگز کاملاً موفق نشده بود؛ هرگز کاملاً شکل را نیافته بود، فرم را، معنا را."),
            StoryParagraph("A man named William Bankes came across the lawn and stopped to look at her canvas.", "مردی به نام ویلیام بنکس از چمن گذشت و ایستاد تا بومش را ببیند."),
            StoryParagraph("'Painting?' he said. 'What are you painting?'", "گفت: «نقاشی؟ چه می‌کشی؟»"),
            StoryParagraph("'Mrs. Ramsay, reading to James,' Lily said. 'But I can't make it out; I can't make it out at all.'", "لیلی گفت: «خانم رامزی را که برای جیمز می‌خواند. اما نمی‌توانم درستش کنم؛ اصلاً نمی‌توانم درستش کنم.»"),
            StoryParagraph("Bankes looked at the canvas, and then at the scene, and then back at the canvas.", "بنکس به بوم نگاه کرد و بعد به صحنه و بعد دوباره به بوم."),
            StoryParagraph("'You have the mother and child, of course,' he said. 'But it isn't quite — the resemblance is not quite there.'", "گفت: «البته مادر و بچه را داری. اما کاملاً نیست — شباهت کاملاً نیست.»"),
            StoryParagraph("'I know,' Lily said. 'That's the problem. I know what I want to paint, but I can't paint it.'", "لیلی گفت: «می‌دانم. مشکل همین است. می‌دانم چه می‌خواهم بکشم اما نمی‌توانم بکشمش.»"),
            StoryParagraph("And she looked at Mrs. Ramsay, who was sitting in the window, reading to James, with a beauty that seemed to Lily to be the essence of life itself.", "و به خانم رامزی نگاه کرد که در پنجره نشسته بود و برای جیمز می‌خواند، با زیبایی‌ای که برای لیلی به نظر می‌رسید جوهر خود زندگی است."),
            StoryParagraph("'She is beautiful,' Bankes said, quietly, as if to himself.", "بنکس آرام گفت گویی با خودش: «او زیباست.»"),
            StoryParagraph("'Yes,' Lily said. 'She is.'", "لیلی گفت: «بله. هست.»"),
            StoryParagraph("And in that moment, in that simple exchange, Lily understood something about life, something she would carry with her forever.", "و در آن لحظه، در آن ردوبدل ساده، لیلی چیزی درباره زندگی فهمید، چیزی که برای همیشه با خود حمل می‌کرد."),
            StoryParagraph("Beauty was not something you possessed; it was something you saw; something that was there, always, in the world, waiting to be noticed.", "زیبایی چیزی نبود که داشته باشی؛ چیزی بود که می‌دیدی؛ چیزی که همیشه آنجا بود، در جهان، منتظر دیده شدن."),
            StoryParagraph("And Mrs. Ramsay, sitting in the window, was one of those moments of beauty — a moment that would not last, that could not last, that had to be preserved in some way.", "و خانم رامزی که در پنجره نشسته بود، یکی از آن لحظه‌های زیبایی بود — لحظه‌ای که دوام نمی‌آورد، نمی‌توانست دوام بیاورد، که باید به نحوی حفظ شود."),
            StoryParagraph("Lily tried to preserve it in her painting; but the painting was not good enough; the painting could never be good enough.", "لیلی تلاش کرد در نقاشی‌اش حفظش کند؛ اما نقاشی به اندازه کافی خوب نبود؛ نقاشی هرگز نمی‌توانست به اندازه کافی خوب باشد."),
            StoryParagraph("The day passed, slowly and beautifully, and the trip to the Lighthouse was postponed, and everyone went about their business in the quiet way of a summer afternoon.", "روز گذشت، آهسته و زیبا و سفر به فانوس دریایی به تعویق افتاد و همه به کارشان رفتند به شیوه ساکت یک بعدازظهر تابستان."),
            StoryParagraph("And so ended the first part of the story, on the lawn of the Ramsays' summer house, on the Isle of Skye, in the summer of 1910.", "و اینگونه بخش نخست داستان در چمن خانه تابستانی رامزی‌ها، در جزیره اسکای، در تابستان ۱۹۱۰ به پایان رسید."),
            StoryParagraph("But the story was not really over; it had only begun.", "اما داستان واقعاً تمام نشده بود؛ تازه آغاز شده بود.")
        )
    )

    // ─────────── فصل ۲: زمان می‌گذرد ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Time Passes", titlePersian = "زمان می‌گذرد",
        paragraphs = listOf(
            StoryParagraph("The summer ended, and the Ramsays went back to London, and the house on the Isle of Skye was shut up for the winter.", "تابستان تمام شد و رامزی‌ها به لندن بازگشتند و خانه جزیره اسکای برای زمستان بسته شد."),
            StoryParagraph("No one came to stay in it; no one walked on the lawn; no one looked out the window at the sea.", "هیچ‌کس نیامد در آن بماند؛ هیچ‌کس روی چمن قدم نزد؛ هیچ‌کس از پنجره به دریا نگاه نکرد."),
            StoryParagraph("The house stood empty, month after month, year after year, and the seasons passed, and nothing and everything changed.", "خانه ماه پس از ماه، سال پس از سال خالی ماند و فصل‌ها گذشتند و هیچ چیز و همه چیز تغییر کرد."),
            StoryParagraph("The wind blew, and the rain fell, and the sun shone, and the wind blew again.", "باد وزید و باران بارید و خورشید تابید و باد دوباره وزید."),
            StoryParagraph("The wallpaper peeled from the walls, slowly, in long strips; the paint faded from the doors; the wood warped and cracked.", "کاغذدیواری آهسته، در نوارهای بلند، از دیوارها کنده شد؛ رنگ از درها محو شد؛ چوب پیچید و ترک خورد."),
            StoryParagraph("Weeds grew in the garden, and then bushes, and then small trees; the paths disappeared; the flower beds became wilderness.", "علف‌های هرز در باغ روییدند و بعد بوته‌ها و بعد درختان کوچک؛ راه‌ها ناپدید شدند؛ باغچه‌های گل وحشی شدند."),
            StoryParagraph("Spiders spun webs in corners; mice nested in mattresses; moths ate holes in curtains; and still the house stood, waiting.", "عنکبوت‌ها در گوشه‌ها تار تنیدند؛ موش‌ها در تشک‌ها لانه کردند؛ پروانه‌ها در پرده‌ها سوراخ خوردند؛ و هنوز خانه ایستاده بود، منتظر."),
            StoryParagraph("In London, in the great world beyond the sea, events of terrible importance were taking place.", "در لندن، در جهان بزرگ آنسوی دریا، رویدادهای با اهمیت هولناک در جریان بود."),
            StoryParagraph("A war had begun, a war that would consume millions of lives, that would change everything, that would end the world everyone had known.", "جنگی آغاز شده بود، جنگی که میلیون‌ها زندگی را می‌بلعید، که همه چیز را تغییر می‌داد، که جهانی که همه می‌شناختند را پایان می‌داد."),
            StoryParagraph("And in the midst of this war, in the midst of the chaos and the death, events were happening to the Ramsay family, events that the novel records in the barest possible way, in brackets, without comment.", "و در میان این جنگ، در میان آشوب و مرگ، رویدادهایی برای خانواده رامزی رخ می‌داد، رویدادهایی که رمان به خالی‌ترین شکل ممکن ثبتشان می‌کند، در پرانتز، بدون توضیح."),
            StoryParagraph("(Mrs. Ramsay died suddenly, one night, in London, and her death was a shock to everyone who had known her.)", "(خانم رامزی یک شب، در لندن، ناگهان مرد و مرگش برای هر کسی که می‌شناختش شوک بود.)"),
            StoryParagraph("(Prue Ramsay, the eldest daughter, married and had a child, and died in childbirth, as her mother had feared she would.)", "(پرو رامزی، دختر بزرگ‌تر، ازدواج کرد و بچه‌دار شد و در زایمان مرد، همانطور که مادرش می‌ترسید.)"),
            StoryParagraph("(Andrew Ramsay, the eldest son, was killed in the war, in France, by a shell, and his death was reported in a telegram.)", "(اندرو رامزی، پسر بزرگ‌تر، در جنگ، در فرانسه، توسط گلوله‌ای کشته شد و مرگش در تلگرامی گزارش شد.)"),
            StoryParagraph("The house continued to stand, on its island, empty and forgotten, and the seasons continued to pass.", "خانه به ایستادن ادامه داد، در جزیره‌اش، خالی و فراموش‌شده و فصل‌ها به گذشتن ادامه دادند."),
            StoryParagraph("Spring came, and the weeds grew, and the birds nested in the chimney, and the wind blew through the empty rooms.", "بهار آمد و علف‌های هرز روییدند و پرندگان در دودکش لانه کردند و باد در اتاق‌های خالی وزید."),
            StoryParagraph("Summer came, and the sun shone on the faded walls, and the flies buzzed in the windows, and nothing happened.", "تابستان آمد و خورشید بر دیوارهای محو شده تابید و مگس‌ها در پنجره‌ها وزوز کردند و هیچ اتفاقی نیفتاد."),
            StoryParagraph("Autumn came, and the leaves fell, and the rain leaked through the roof, and the damp crept up the walls.", "پاییز آمد و برگ‌ها ریختند و باران از سقف نشت کرد و نم در دیوارها بالا رفت."),
            StoryParagraph("Winter came, and the frost crept in, and the snow piled up against the doors, and the house was silent.", "زمستان آمد و سرما به داخل خزید و برف مقابل درها انبار شد و خانه ساکت شد."),
            StoryParagraph("Then spring again; then summer; then autumn; then winter; and so the years passed, ten of them, with no one to count them.", "بعد دوباره بهار؛ بعد تابستان؛ بعد پاییز؛ بعد زمستان؛ و اینگونه سال‌ها گذشتند، ده تا، بدون کسی که بشماردشان."),
            StoryParagraph("Meanwhile, in the wider world, the war ended, and peace came, and the world began to rebuild itself.", "در همین حال، در جهان گسترده‌تر، جنگ تمام شد و صلح آمد و جهان شروع کرد به بازسازی خودش."),
            StoryParagraph("And slowly, tentatively, the family began to think about the house again, and about the summer, and about the time that had passed.", "و آهسته، با تردید، خانواده شروع کرد به فکر کردن دوباره درباره خانه و درباره تابستان و درباره زمانی که گذاشته بود."),
            StoryParagraph("The housekeeper, an old woman named Mrs. McNab, who had been coming to the house every few months for years, received a letter.", "خانم مک‌ناب، پیرزنی که سال‌ها هر چند ماه به خانه می‌آمد، نامه‌ای دریافت کرد."),
            StoryParagraph("The letter said that the family was coming back, that the house must be prepared, that everything must be made ready.", "نامه می‌گفت خانواده برمی‌گردد، خانه باید آماده شود، همه چیز باید مهیا شود."),
            StoryParagraph("And so Mrs. McNab came, with her mops and her brooms and her buckets, and she began the great work of cleaning, of restoring, of bringing the house back to life.", "و اینگونه خانم مک‌ناب آمد، با جاروها و برس‌ها و سطل‌هایش و کار بزرگ تمیز کردن را آغاز کرد، بازگرداندن، زنده کردن دوباره خانه."),
            StoryParagraph("She swept the dust of ten years from the floors; she washed the windows; she aired the rooms.", "گرد و غبار ده سال را از کف‌ها جارو کرد؛ پنجره‌ها را شست؛ اتاق‌ها را هوا داد."),
            StoryParagraph("She found the bodies of birds in the chimney; she found mushrooms growing in the corners; she found the skeleton of a rat in the pantry.", "جسد پرندگانی در دودکش یافت؛ قارچ‌هایی در گوشه‌ها روییده یافت؛ اسکلت موشی در انبار یافت."),
            StoryParagraph("And with each sweep, with each wash, with each mended pane, the house came back to itself.", "و با هر جارو، با هر شستشو، با هر شیشه ترمیم‌شده، خانه به خودش بازگشت."),
            StoryParagraph("Meanwhile, in London, in Paris, in the world, the survivors of the family gathered, and they decided to return to the house, to the summer, to the place where their mother had been.", "در همین حال، در لندن، در پاریس، در جهان، بازماندگان خانواده جمع شدند و تصمیم گرفتند به خانه برگردند، به تابستان، به جایی که مادرشان بوده."),
            StoryParagraph("And so, at last, on a summer morning, ten years after the events of the first part, the survivors arrived.", "و اینگونه، سرانجام، در صبحی تابستانی، ده سال پس از رویدادهای بخش نخست، بازماندگان رسیدند."),
            StoryParagraph("Mr. Ramsay was older now, greyer, sadder; his wife was gone, his son was gone, his daughter was gone; and he had no one to demand love from anymore.", "آقای رامزی حالا پیرتر بود، خاکستری‌تر، غمگین‌تر؛ همسرش رفته بود، پسرش رفته، دخترش رفته؛ و دیگر کسی نداشت که از او عشق طلب کند."),
            StoryParagraph("Two of his children were with him: James, now sixteen, and Cam, now fourteen; and Lily Briscoe had come too, to finish her painting.", "دو تن از بچه‌هایش با او بودند: جیمز، حالا شانزده ساله و کم، حالا چهارده ساله؛ و لیلی بریسکو هم آمده بود تا نقاشی‌اش را تمام کند."),
            StoryParagraph("And so the story resumed, ten years later, in the same house, in the same bay, with the same sea and the same sky.", "و اینگونه داستان ده سال بعد از سر گرفته شد، در همان خانه، در همان خلیج، با همان دریا و همان آسمان."),
            StoryParagraph("But everything had changed; everyone had changed; and nothing would ever be the same again.", "اما همه چیز تغییر کرده بود؛ همه تغییر کرده بودند؛ و هیچ چیز هرگز همان نمی‌شد."),
            StoryParagraph("And in the bay, still standing, still shining, still waiting, was the Lighthouse — unchanged, unchanging, eternal.", "و در خلیج، هنوز ایستاده، هنوز درخشان، هنوز منتظر، فانوس دریایی بود — بدون تغییر، بدون تغییرپذیری، ابدی.")
        )
    )

    // ─────────── فصل ۳: فانوس دریایی ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Lighthouse", titlePersian = "فانوس دریایی",
        paragraphs = listOf(
            StoryParagraph("In the morning, the weather was fine; the sky was blue, the sea was calm, and Mr. Ramsay announced that the trip to the Lighthouse would take place at last.", "صبح، هوا خوب بود؛ آسمان آبی، دریا آرام و آقای رامزی اعلام کرد که سفر به فانوس دریایی سرانجام انجام می‌شود."),
            StoryParagraph("James, who was sixteen now, who had heard this news many times before, felt no joy at the announcement; only a dull resentment.", "جیمز که حالا شانزده ساله بود و این خبر را بارها پیش از این شنیده بود، هیچ شادی در این اعلام حس نکرد؛ تنها دلخوری کدری."),
            StoryParagraph("He did not want to go; he did not want to be with his father; he did not want to pretend that they were a happy family.", "نمی‌خواست برود؛ نمی‌خواست با پدرش باشد؛ نمی‌خواست تظاهر کند خانواده خوشبختی هستند."),
            StoryParagraph("But he went, because there was no way to refuse, and he sat in the boat with his father and with Cam and with an old fisherman who was to sail them.", "اما رفت، چون راهی برای امتناع نبود و در قایق با پدرش و کم و ماهیگیر پیری که قرار بود دریانوردی‌شان کند نشست."),
            StoryParagraph("Cam was watching the wake of the boat, the long trail of foam left behind on the water, and she was thinking about her mother.", "کم به دنباله قایق نگاه می‌کرد، به رد طولانی کف باقی‌مانده روی آب و به مادرش فکر می‌کرد."),
            StoryParagraph("She remembered her mother's hands, and her mother's voice, and her mother's love; and she remembered how much her mother had loved them all.", "دست‌های مادرش را به یاد آورد و صدایش و عشقش؛ و به یاد آورد که مادرش چقدر همه‌شان را دوست داشت."),
            StoryParagraph("And she thought about how strange it was, that someone so full of life could simply disappear, could simply cease to be.", "و فکر کرد چه عجیب است، کسی اینقدر پر از زندگی بتواند به‌سادگی ناپدید شود، به‌سادگی از هستی باز ایستد."),
            StoryParagraph("Mr. Ramsay sat in the stern of the boat, with his hand on the tiller, and he watched the water, and he thought about his wife.", "آقای رامزی در انتهای قایق نشست، دستش روی سکان و به آب نگاه کرد و به همسرش فکر کرد."),
            StoryParagraph("He had loved her, in his way; and he had needed her, in his way; and he had never told her any of it.", "او را دوست داشته بود، به شیوه خودش؛ و به او نیاز داشت، به شیوه خودش؛ و هیچ‌کدام را هرگز نگفته بود."),
            StoryParagraph("He had never told her that she was beautiful, or that she was wise, or that she was kind.", "هرگز نگفته بود که زیباست، یا فرزانه، یا مهربان."),
            StoryParagraph("He had never told her that he was grateful for her, or that he was lost without her, or that he would never be the same.", "هرگز نگفته بود سپاسگزارش است، یا بدون او گم است، یا هرگز همان نخواهد بود."),
            StoryParagraph("'Come on, James,' he said, and his voice was gentle for once. 'Keep her steady. You're steering well.'", "گفت: «بیا جیمز.» و برای یک بار صدایش لطیف بود. «نگهش دار. خوب هدایت می‌کنی.»"),
            StoryParagraph("James heard the words, and for a moment, he did not know what to feel.", "جیمز کلمات را شنید و لحظه‌ای نمی‌دانست چه حس کند."),
            StoryParagraph("His father had never praised him before, not once, not ever; and now, at this moment, on this boat, he had been praised.", "پدرش هرگز تحسینش نکرده بود، حتی یک بار، هرگز؛ و حالا، در این لحظه، در این قایق، تحسین شده بود."),
            StoryParagraph("And something in James shifted; something hard began to soften; something old began to heal.", "و چیزی در جیمز جابه‌جا شد؛ چیزی سخت شروع به نرم شدن کرد؛ چیزی کهنه شروع به شفا یافتن کرد."),
            StoryParagraph("He looked at his father, and for the first time in years, he did not hate him.", "به پدرش نگاه کرد و برای نخستین بار در سال‌ها، از او متنفر نبود."),
            StoryParagraph("He saw his father as he was: an old man, tired, lonely, disappointed; a man who had loved a woman and lost her; a man who had tried and failed.", "پدرش را همانطور که بود دید: پیرمردی، خسته، تنها، ناامید؛ مردی که زنی را دوست داشته و از دست داده؛ مردی که تلاش کرده و شکست خورده."),
            StoryParagraph("And in that seeing, in that understanding, James felt something that he had never felt before: compassion.", "و در آن دیدن، در آن فهم، جیمز چیزی حس کرد که هرگز قبلاً حس نکرده بود: شفقت."),
            StoryParagraph("The boat moved across the bay, and the Lighthouse grew larger, and the little group sat in silence, each lost in their own thoughts.", "قایق در خلیج پیش رفت و فانوس دریایی بزرگ‌تر شد و گروه کوچک در سکوت نشستند، هر یک غرق در افکار خودش."),
            StoryParagraph("And then, at last, they arrived.", "و بعد، سرانجام، رسیدند."),
            StoryParagraph("The Lighthouse was not what they had expected; it was not grand, not beautiful, not mysterious.", "فانوس دریایی آن چیزی نبود که انتظار داشتند؛ باشکوه نبود، زیبا نبود، مرموز نبود."),
            StoryParagraph("It was simply a tower, whitewashed, with a light at the top and a door at the bottom.", "تنها برجی بود، سفیدکاری‌شده، با نوری در بالا و دری در پایین."),
            StoryParagraph("But it was the Lighthouse; and to have reached it, after all those years, after all that longing, was something.", "اما فانوس دریایی بود؛ و رسیدنش، پس از تمام آن سال‌ها، پس از تمام آن اشتیاق، چیزی بود."),
            StoryParagraph("James stepped onto the rock, and he looked back at the house, and he saw it as his mother had seen it — a small, bright thing on the edge of the sea.", "جیمز روی صخره قدم گذاشت و به خانه نگاه کرد و آن را همانطور که مادرش دیده بود دید — چیز کوچک و روشنی در لبه دریا."),
            StoryParagraph("And he understood, at last, what she had meant when she said that the Lighthouse was important; it was important because they had wanted to go there, and because wanting was itself a kind of light.", "و سرانجام فهمید مادرش وقتی می‌گفت فانوس دریایی مهم است منظورش چه بود؛ مهم بود چون می‌خواستند به آنجا بروند و چون خواستن خودش نوعی نور بود."),
            StoryParagraph("Meanwhile, back at the house, Lily Briscoe was trying to finish her painting.", "در همین حال، در خانه، لیلی بریسکو تلاش می‌کرد نقاشی‌اش را تمام کند."),
            StoryParagraph("Mr. Ramsay had gone, and the house was quiet, and she was alone with her canvas, and she was struggling as she had always struggled.", "آقای رامزی رفته بود و خانه ساکت بود و او با بومش تنها بود و مثل همیشه دست‌وپنجه نرم می‌کرد."),
            StoryParagraph("She could not see the shape; she could not find the line; she could not make the colors speak.", "شکل را نمی‌دید؛ خط را نمی‌یافت؛ نمی‌توانست رنگ‌ها را به سخن گفتن وادار کند."),
            StoryParagraph("And then, suddenly, unexpectedly, she thought of Mrs. Ramsay — not as she had been, but as she was, in memory, in love.", "و بعد، ناگهان، به‌طور غیرمنتظره، به خانم رامزی فکر کرد — نه آنطور که بوده بود، بلکه آنطور که بود، در حافظه، در عشق."),
            StoryParagraph("And she saw it — the shape, the line, the meaning; she saw what she had been trying to paint all those years.", "و دیدش — شکل را، خط را، معنا را؛ دید چه چیزی را تمام آن سال‌ها تلاش کرده بود بکشد."),
            StoryParagraph("She picked up her brush, and she made a mark, a single decisive mark, in the center of the canvas.", "قلم‌مو را برداشت و نشانه‌ای گذاشت، نشانه‌ای واحد و قاطع، در مرکز بوم."),
            StoryParagraph("And she knew, in that moment, that she had done it; that she had made something; that she had captured, however briefly, however imperfectly, the truth of life.", "و در آن لحظه دانست که کرده بودش؛ که چیزی ساخته بود؛ که ثبت کرده بود، هرچند گذرا، هرچند ناقص، حقیقت زندگی را."),
            StoryParagraph("And she stood there, in the empty house, looking at her canvas, and she felt a peace that she had never felt before.", "و آنجا ایستاد، در خانه خالی، به بومش نگاه کرد و آرامشی حس کرد که هرگز قبلاً حس نکرده بود."),
            StoryParagraph("She had finished the painting; she had reached her Lighthouse.", "نقاشی را تمام کرده بود؛ به فانوس دریایی خودش رسیده بود."),
            StoryParagraph("And so the story ended, with two journeys completed, two visions achieved, two Lighthouses reached.", "و اینگونه داستان پایان یافت، با دو سفر کامل‌شده، دو بینش به دست آمده، دو فانوس دریایی رسیده."),
            StoryParagraph("James had reached his mother's love; Lily had reached her art's truth; and both had found, in the reaching, something like peace.", "جیمز به عشق مادرش رسیده بود؛ لیلی به حقیقت هنرش؛ و هر دو در رسیدن، چیزی شبیه آرامش یافته بودند."),
            StoryParagraph("The Lighthouse stood in the bay, unchanged, unchanging, eternal.", "فانوس دریایی در خلیج ایستاده بود، بدون تغییر، بدون تغییرپذیری، ابدی."),
            StoryParagraph("And the light shone, as it always had, across the dark water, guiding the lost, comforting the lonely, promising that there was a way home.", "و نور می‌تابید، همانطور که همیشه تابیده بود، روی آب تاریک، راهنمایی گمشدگان، تسلی تنهایان، وعده اینکه راهی به خانه هست.")
        )
    )

    // ─────────── فصل ۴: لیلی بریسکو ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Lily Briscoe", titlePersian = "لیلی بریسکو",
        paragraphs = listOf(
            StoryParagraph("Lily Briscoe was thirty-three years old, unmarried, and a painter; and in the world of 1920s England, that made her an anomaly.", "لیلی بریسکو سی و سه ساله بود، مجرد و نقاش؛ و در جهان انگلستان دهه ۱۹۲۰، این او را ناهنجاری می‌کرد."),
            StoryParagraph("Women were expected to marry, to have children, to take care of a household; they were not expected to have careers, or opinions, or ambitions of their own.", "انتظار می‌رفت زنان ازدواج کنند، بچه‌دار شوند، از خانه مراقبت کنند؛ انتظار نمی‌رفت شغل داشته باشند، یا نظر، یا جاه‌طلبی‌های خودشان."),
            StoryParagraph("But Lily had a gift, a real gift for painting, and she could not deny it, and she did not want to deny it.", "اما لیلی استعدادی داشت، استعدادی واقعی برای نقاشی و نمی‌توانست انکارش کند و نمی‌خواست انکارش کند."),
            StoryParagraph("She had been painting since she was a girl, and she had studied in Paris, and she had exhibited, and she had been praised, and she had been ignored.", "از دختری نقاشی می‌کرد و در پاریس تحصیل کرده بود و نمایش داده بود و تحسین شده بود و نادیده گرفته شده بود."),
            StoryParagraph("But none of it mattered, in the end; what mattered was the painting itself, the daily struggle to see something clearly and to set it down on canvas.", "اما هیچ‌کدام در پایان مهم نبود؛ آنچه مهم بود خود نقاشی بود، مبارزه روزانه برای دیدن چیزی با وضوح و ثبتش روی بوم."),
            StoryParagraph("Lily had come to the Ramsays' summer house that year to paint; and she had come back, ten years later, to finish what she had begun.", "لیلی آن سال برای نقاشی به خانه تابستانی رامزی‌ها آمده بود؛ و ده سال بعد بازگشته بود تا آنچه را آغاز کرده بود تمام کند."),
            StoryParagraph("She had come back for Mrs. Ramsay, as much as for the painting; she had loved Mrs. Ramsay, in her way, in a way she had never quite expressed.", "بازگشته بود برای خانم رامزی، به همان اندازه که برای نقاشی؛ خانم رامزی را دوست داشت، به شیوه خودش، به شیوه‌ای که هرگز کاملاً بیان نکرده بود."),
            StoryParagraph("Mrs. Ramsay had been everything that Lily was not: beautiful, feminine, warm, social; and yet, she had also been a woman who understood the value of a woman who was different.", "خانم رامزی همه چیزی بود که لیلی نبود: زیبا، زنانه، گرم، اجتماعی؛ و با این حال، او هم زنی بود که ارزش زن متفاوتی را می‌فهمید."),
            StoryParagraph("'Women can't paint,' Charles Tansley, a young philosopher, had said once, at a dinner at the Ramsays', years ago.", "چارلز تنسلی، فیلسوف جوانی، سال‌ها پیش در شامی در خانه رامزی‌ها گفته بود: «زنان نمی‌توانند نقاشی کنند.»"),
            StoryParagraph("Lily had been enraged, and had held her tongue, and had remembered the remark for years.", "لیلی خشمگین شده بود و زبانش را نگه داشته بود و این حرف را سال‌ها به یاد داشت."),
            StoryParagraph("And now, in the empty house, in the room where Mrs. Ramsay had once sat, Lily picked up her brush and began to paint.", "و حالا، در خانه خالی، در اتاقی که خانم رامزی روزی در آن نشسته بود، لیلی قلم‌مویش را برداشت و شروع به نقاشی کرد."),
            StoryParagraph("She painted for hours, and she painted for days, and slowly, the painting began to take shape.", "ساعت‌ها نقاشی کرد و روزها و آهسته، نقاشی شروع کرد به شکل گرفتن."),
            StoryParagraph("It was not the painting she had planned; it was not the painting she had imagined; it was something else entirely, something that had come from somewhere deeper.", "نقاشی‌ای نبود که نقشه کشیده بود؛ نقاشی‌ای نبود که تصور کرده بود؛ چیز کاملاً دیگری بود، چیزی از جایی عمیق‌تر آمده بود."),
            StoryParagraph("It was a painting about Mrs. Ramsay, but it was also a painting about Lily, and about all women, and about the struggle to be seen in a world that did not want to see you.", "نقاشی‌ای بود درباره خانم رامزی، اما همچنین نقاشی‌ای بود درباره لیلی، و درباره همه زنان و درباره مبارزه برای دیده شدن در جهانی که نمی‌خواست ببیندت."),
            StoryParagraph("And when she was finished, when she stepped back from the canvas and looked at what she had made, she knew, with absolute certainty, that she had succeeded.", "و وقتی تمام شد، وقتی از بوم عقب رفت و به آنچه ساخته بود نگاه کرد، با یقین مطلق دانست که موفق شده بود."),
            StoryParagraph("Not that the painting was perfect; it was not; it was imperfect, flawed, incomplete, like all human creations.", "نه اینکه نقاشی کامل بود؛ نبود؛ ناقص بود، معیوب، ناتمام، همچون همه آفریده‌های انسانی."),
            StoryParagraph("But it was true; it was honest; it was hers; and that was enough.", "اما راستین بود؛ صادق بود؛ مال خودش بود؛ و همین کافی بود."),
            StoryParagraph("'I have had my vision,' she said, quietly, to the empty room, to the absent Mrs. Ramsay, to the world.", "آرام گفت: «رؤیایم را داشته‌ام.» به اتاق خالی، به خانم رامزی غایب، به جهان."),
            StoryParagraph("And then she stopped, and she rested, and she allowed herself to feel what she had not allowed herself to feel for years: peace.", "و بعد ایستاد و آسود و به خودش اجازه داد چیزی را حس کند که سال‌ها به خودش اجازه نداده بود: آرامش."),
            StoryParagraph("Because Lily's story is not just a story about a painting; it is a story about a woman finding her own voice, in a world that wanted her silent.", "زیرا داستان لیلی تنها داستانی درباره یک نقاشی نیست؛ داستانی درباره زنی است که صدای خودش را می‌یابد، در جهانی که می‌خواست ساکتش باشد."),
            StoryParagraph("It is a story about a woman finding her own vision, in a world that wanted her to see only what it showed her.", "داستانی است درباره زنی که بینش خودش را می‌یابد، در جهانی که می‌خواست تنها آنچه نشانش می‌داد را ببیند."),
            StoryParagraph("It is a story about a woman finding her own truth, in a world that wanted her to accept the truth of others.", "داستانی است درباره زنی که حقیقت خودش را می‌یابد، در جهانی که می‌خواست حقیقت دیگران را بپذیرد."),
            StoryParagraph("And in finding these things, in reaching this vision, Lily became a kind of hero; not a hero of battles or of adventures, but a hero of the spirit, a hero of the mind, a hero of the self.", "و در یافتن این چیزها، در رسیدن به این بینش، لیلی نوعی قهرمان شد؛ نه قهرمان نبردها یا ماجراجویی‌ها، بلکه قهرمان روح، قهرمان ذهن، قهرمان خود."),
            StoryParagraph("She had come to the Ramsays' house as a young woman, uncertain of herself, dependent on the approval of others.", "به خانه رامزی‌ها به‌عنوان زنی جوان آمده بود، نامطمئن از خودش، وابسته به تأیید دیگران."),
            StoryParagraph("She had returned, ten years later, as a woman who knew who she was, who knew what she wanted, who knew how to get it.", "ده سال بعد بازگشته بود، به‌عنوان زنی که می‌دانست کیست، می‌دانست چه می‌خواهد، می‌دانست چگونه به دستش آورد."),
            StoryParagraph("And the painting, the painting she had finally finished, was the proof of that transformation; it was the visible sign of the invisible change.", "و نقاشی، نقاشی‌ای که سرانجام تمام کرده بود، اثبات آن دگرگونی بود؛ نشانه مرئی تغییر نامرئی."),
            StoryParagraph("In Virginia Woolf's world, in the world of the 1920s, in the world of literature, Lily Briscoe was a radical figure.", "در جهان ویرجینیا وولف، در جهان دهه ۱۹۲۰، در جهان ادبیات، لیلی بریسکو چهره‌ای رادیکال بود."),
            StoryParagraph("She was a woman who chose art over marriage, self-realization over social expectation, truth over comfort.", "زنی بود که هنر را بر ازدواج ترجیح داده بود، خودشکوفایی را بر انتظار اجتماعی، حقیقت را بر راحتی."),
            StoryParagraph("And Woolf, through Lily, was saying something that had not been said before, or not often enough: that women's lives matter, that women's visions matter, that women's art matters.", "و وولف، از طریق لیلی، چیزی می‌گفت که قبلاً گفته نشده بود، یا به اندازه کافی گفته نشده بود: که زندگی‌های زنان اهمیت دارد، بینش‌های زنان اهمیت دارد، هنر زنان اهمیت دارد."),
            StoryParagraph("This was radical, in 1927, when the novel was published; it was radical, in the world of English literature, which had been dominated by men.", "این در ۱۹۲۷، وقتی رمان منتشر شد، رادیکال بود؛ در جهان ادبیات انگلیسی، که توسط مردان تسلط یافته بود، رادیکال بود."),
            StoryParagraph("But Woolf did not shout; she did not preach; she simply showed, in the quiet story of a woman painting on a lawn, what it meant to be a woman artist.", "اما وولف فریاد نزد؛ موعظه نکرد؛ تنها نشان داد، در داستان آرام زنی که روی چمن نقاشی می‌کند، معنای زن هنرمند بودن."),
            StoryParagraph("And that quiet showing was more powerful than any shouting could ever be.", "و آن نشان دادن آرام از هر فریادی قدرتمندتر بود."),
            StoryParagraph("Lily Briscoe, in the end, was not a great painter; her paintings did not hang in museums; her name was not remembered.", "لیلی بریسکو در پایان نقاش بزرگی نبود؛ نقاشی‌هایش در موزه‌ها آویزان نمی‌شد؛ نامش به یاد نمی‌آمد."),
            StoryParagraph("But she had painted, and she had painted truly, and she had reached her vision; and that, Woolf suggests, is enough.", "اما نقاشی کرده بود و راستین نقاشی کرده بود و به بینشش رسیده بود؛ و این، وولف پیشنهاد می‌دهد، کافی است."),
            StoryParagraph("To create something, to see something clearly, to say something honestly — that is the highest achievement available to any human being.", "آفریدن چیزی، دیدن چیزی با وضوح، گفتن چیزی صادقانه — این بالاترین دستاوردی است که برای هر انسانی در دسترس است."),
            StoryParagraph("And Lily Briscoe had achieved it; and so, in her own way, had Mrs. Ramsay; and so, in his own way, had Mr. Ramsay; and so, in their own ways, had all of them.", "و لیلی بریسکو به آن رسیده بود؛ و اینگونه، به شیوه خودش، خانم رامزی هم؛ و اینگونه، به شیوه خودش، آقای رامزی هم؛ و اینگونه، به شیوه‌های خودشان، همه‌شان."),
            StoryParagraph("For life is made of such small achievements, such quiet victories; and it is in these, and not in the great events, that we find our meaning.", "زیرا زندگی از چنین دستاوردهای کوچکی ساخته شده، چنین پیروزی‌های ساکتی؛ و در این‌ها، نه در رویدادهای بزرگ، معنایمان را می‌یابیم.")
        )
    )

    // ─────────── فصل ۵: خانواده و خاطره ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "Family and Memory", titlePersian = "خانواده و خاطره",
        paragraphs = listOf(
            StoryParagraph("The Ramsay family was large, and complicated, and full of love and full of pain.", "خانواده رامزی بزرگ بود و پیچیده و پر از عشق و پر از درد."),
            StoryParagraph("There were eight children in all, born over many years, each of them different, each of them shaped by the same forces.", "در کل هشت فرزند بودند، در طول سال‌های بسیار زاده شده، هر یک متفاوت، هر یک توسط همان نیروها شکل گرفته."),
            StoryParagraph("Andrew, the eldest son, had been killed in the war; he had been a mathematician, brilliant and quiet, and his death had been a blow from which the family never quite recovered.", "اندرو، پسر بزرگ‌تر، در جنگ کشته شده بود؛ ریاضیدانی بوده، درخشان و ساکت و مرگش ضربه‌ای بود که خانواده هرگز کاملاً از آن بهبود نیافت."),
            StoryParagraph("Prue, the eldest daughter, had married and had died in childbirth; she had been beautiful and gentle, like her mother, and her death had seemed to echo her mother's.", "پرو، دختر بزرگ‌تر، ازدواج کرده و در زایمان مرده بود؛ زیبا و لطیف بوده، مثل مادرش و مرگش به نظر می‌رسید پژواک مرگ مادرش باشد."),
            StoryParagraph("Nancy, the second daughter, had become a wanderer; she had never married, never settled, never quite found her place in the world.", "نانسی، دختر دوم، سرگردان شده بود؛ هرگز ازدواج نکرده، هرگز ساکن نشده، هرگز کاملاً جایش را در جهان نیافته بود."),
            StoryParagraph("Roger, the second son, had become a soldier, like his father before him; he had survived the war, but he had not survived unchanged.", "راجر، پسر دوم، سرباز شده بود، مثل پدرش پیش از او؛ از جنگ جان به‌در برده بود اما بدون تغییر جان به‌در نبرده بود."),
            StoryParagraph("Cass, the third daughter, had become a doctor; she had dedicated her life to healing, perhaps because she had seen so much suffering in her own family.", "کس، دختر سوم، دکتر شده بود؛ زندگی‌اش را وقف شفا کرده بود، شاید چون رنج بسیاری در خانواده خودش دیده بود."),
            StoryParagraph("Jasper, the third son, had become a writer; he had tried to capture in his books what he could not capture in his life.", "جاسپر، پسر سوم، نویسنده شده بود؛ تلاش کرده بود در کتاب‌هایش چیزی را ثبت کند که در زندگی‌اش نمی‌توانست."),
            StoryParagraph("Rose, the fourth daughter, had died young, of an illness, and had been forgotten by most of the family.", "رز، دختر چهارم، جوان مرده بود، از بیماری و توسط بیشتر خانواده فراموش شده بود."),
            StoryParagraph("And James, the youngest son, who had once dreamed of going to the Lighthouse, had grown up angry and bitter, and had only begun to forgive his father in the final days of the story.", "و جیمز، پسر کوچک‌ترین، که روزی آرزوی رفتن به فانوس دریایی را داشت، عصبانی و تلخ بزرگ شده بود و تنها در روزهای آخر داستان شروع کرده بود به بخشیدن پدرش."),
            StoryParagraph("Each of these children had loved their mother, in their own ways; each had been shaped by her love; each had been wounded by her death.", "هر یک از این بچه‌ها مادرشان را دوست داشته بود، به شیوه‌های خودشان؛ هر یک توسط عشقش شکل گرفته بود؛ هر یک توسط مرگش زخم خورده بود."),
            StoryParagraph("And each of them had loved, or feared, or resented their father, in ways that they did not always understand.", "و هر یک از آنان پدرشان را دوست داشته بود، یا ترسیده بود، یا دلخور بود، به شیوه‌هایی که همیشه نمی‌فهمیدند."),
            StoryParagraph("Mr. Ramsay was, in many ways, a difficult man; he was brilliant, but he was also demanding, and cold, and often cruel.", "آقای رامزی از بسیاری جهات مردی دشوار بود؛ درخشان بود اما پرتوقع هم بود و سرد و اغلب بی‌رحم."),
            StoryParagraph("He needed constant reassurance, constant attention, constant love; and when he did not get them, he sulked, or raged, or withdrew into silence.", "به اطمینان دائمی نیاز داشت، توجه دائمی، عشق دائمی؛ و وقتی نمی‌گرفتشان، قهر می‌کرد، یا خشمگین می‌شد، یا به سکوت عقب‌نشینی می‌کرد."),
            StoryParagraph("He had been jealous of his children, especially of James, who had received so much of his mother's love.", "به بچه‌هایش حسادت می‌کرد، به‌ویژه به جیمز، که اینقدر از عشق مادرش دریافت کرده بود."),
            StoryParagraph("And he had been jealous of his wife's attention to others, to guests, to friends, to anyone who was not himself.", "و به توجه همسرش به دیگران حسادت می‌کرد، به مهمانان، به دوستان، به هر کسی که خودش نبود."),
            StoryParagraph("But he had also loved her, deeply and truly, in the way that he was capable of love.", "اما او را هم دوست داشت، عمیق و راستین، به شیوه‌ای که در توانش بود."),
            StoryParagraph("And when she died, something in him died too; he was never the same after that; he was never fully himself.", "و وقتی او مرد، چیزی در او هم مرد؛ بعد از آن هرگز همان نشد؛ هرگز کاملاً خودش نشد."),
            StoryParagraph("So the story of the Ramsays is a story of family: of the love that binds people together, and of the pain that tears them apart.", "پس داستان رامزی‌ها داستان خانواده است: عشقی که انسان‌ها را به هم می‌بندد و دردی که از هم می‌دردشان."),
            StoryParagraph("It is a story of memory: of how the past lives within us, shaping our present, haunting our future.", "داستان حافظه است: اینکه گذشته چگونه درون ما زندگی می‌کند، حالمان را شکل می‌دهد، آینده‌مان را تسخیر می‌کند."),
            StoryParagraph("It is a story of time: of how it passes, and how it does not pass; of how it heals, and how it does not heal.", "داستان زمان است: اینکه چگونه می‌گذرد و چگونه نمی‌گذرد؛ چگونه شفا می‌دهد و چگونه نمی‌دهد."),
            StoryParagraph("It is a story of love: of the many kinds of love, and the many ways of loving, and the impossibility of ever fully expressing love.", "داستان عشق است: انواع بسیاری از عشق و شیوه‌های بسیاری از عشق ورزیدن و ناممکن بودن هرگز کاملاً بیان کردن عشق."),
            StoryParagraph("And it is a story of art: of the need to create, to capture, to preserve; of the way art can save us when nothing else can.", "و داستان هنر است: نیاز به آفریدن، به ثبت کردن، به حفظ کردن؛ شیوه‌ای که هنر می‌تواند نجاتمان دهد وقتی هیچ چیز دیگری نمی‌تواند."),
            StoryParagraph("The novel is not about great events, or about heroes, or about grand themes; it is about the ordinary lives of ordinary people, and the extraordinary things that happen within them.", "رمان درباره رویدادهای بزرگ نیست، یا درباره قهرمانان، یا درباره مضامین بزرگ؛ درباره زندگی‌های معمولی مردم معمولی است و چیزهای فوق‌العاده‌ای که درونشان رخ می‌دهد."),
            StoryParagraph("It is about a summer day, and a postponed trip, and a dinner party, and a painting.", "درباره روزی تابستانی است و سفری به تعویق افتاده و شامی و نقاشی‌ای."),
            StoryParagraph("It is about a mother's love, and a father's need, and a son's anger, and a painter's vision.", "درباره عشق مادری است و نیاز پدری و خشم پسری و بینش نقاشی."),
            StoryParagraph("It is about the way that time passes, and the way that memory holds; about the way that death comes, and the way that life continues.", "درباره شیوه‌ای است که زمان می‌گذرد و شیوه‌ای که حافظه نگه می‌دارد؛ شیوه‌ای که مرگ می‌آید و شیوه‌ای که زندگی ادامه می‌یابد."),
            StoryParagraph("And it is about the Lighthouse, always the Lighthouse: the symbol of hope, of aspiration, of the light that shines across the darkness.", "و درباره فانوس دریایی است، همیشه فانوس دریایی: نماد امید، آرزو، نوری که در تاریکی می‌تابد."),
            StoryParagraph("For the Ramsays, the Lighthouse was a destination; it was something they wanted to reach, something they dreamed of reaching.", "برای رامزی‌ها، فانوس دریایی مقصدی بود؛ چیزی بود که می‌خواستند به آن برسند، چیزی که آرزوی رسیدنش را داشتند."),
            StoryParagraph("For us, the readers, the Lighthouse is also a symbol: it is the thing we are all reaching toward, whatever it may be — love, or art, or truth, or peace.", "برای ما، خوانندگان، فانوس دریایی هم نمادی است: چیزی است که همه‌مان به سمتش می‌رویم، هر چه باشد — عشق، یا هنر، یا حقیقت، یا آرامش."),
            StoryParagraph("And whether we reach it or not, the reaching is what matters; the journey is what matters; the willingness to set out, to try, to hope.", "و خواه به آن برسیم یا نه، رسیدن است که اهمیت دارد؛ سفر است که اهمیت دارد؛ آمادگی برای راه افتادن، برای تلاش، برای امید."),
            StoryParagraph("And so, in the end, we are all like James, like Cam, like Lily, like Mr. Ramsay: we are all sailing toward our own Lighthouses, across our own dark water, hoping that the light will guide us home.", "و اینگونه، در پایان، همه‌مان مثل جیمز هستیم، مثل کم، مثل لیلی، مثل آقای رامزی: همه‌مان به سمت فانوس‌های دریایی خودمان دریانوردی می‌کنیم، روی آب تاریک خودمان، امیدوار که نور راه خانه را نشانمان دهد.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("To the Lighthouse, published in 1927, is one of the most beautiful and most difficult novels of the twentieth century.", "به سوی فانوس دریایی، منتشرشده در ۱۹۲۷، یکی از زیباترین و دشوارترین رمان‌های قرن بیستم است."),
            StoryParagraph("It tells the story of the Ramsay family, over two days ten years apart, in a summer house on the Isle of Skye.", "داستان خانواده رامزی را در دو روز با ده سال فاصله، در خانه تابستانی جزیره اسکای، تعریف می‌کند."),
            StoryParagraph("But it is not really about the family, or the house, or the island; it is about consciousness, about time, about memory, about love.", "اما واقعاً درباره خانواده نیست، یا خانه، یا جزیره؛ درباره آگاهی است، درباره زمان، درباره حافظه، درباره عشق."),
            StoryParagraph("Woolf uses the technique of stream of consciousness, in which the narrative flows through the minds of the characters, capturing their thoughts as they occur.", "وولف تکنیک جریان آگاهی را استفاده می‌کند، که در آن روایت از ذهن شخصیت‌ها جاری می‌شود و افکارشان را همانطور که رخ می‌دهند ثبت می‌کند."),
            StoryParagraph("In this way, she shows us that consciousness is not linear but associative; that time is not chronological but psychological; that reality is not objective but subjective.", "به این شیوه، نشانمان می‌دهد آگاهی خطی نیست بلکه انجمنی؛ زمان زمانی نیست بلکه روانی؛ واقعیت عینی نیست بلکه ذهنی."),
            StoryParagraph("The novel is divided into three parts: The Window, Time Passes, and The Lighthouse.", "رمان به سه بخش تقسیم می‌شود: پنجره، زمان می‌گذرد و فانوس دریایی."),
            StoryParagraph("The first part, The Window, takes place in a single afternoon in 1910; it introduces the characters, their relationships, their tensions, their loves.", "بخش نخست، پنجره، در بعدازظهری واحد در ۱۹۱۰ رخ می‌دهد؛ شخصیت‌ها را معرفی می‌کند، روابطشان، تنش‌هایشان، عشق‌هایشان."),
            StoryParagraph("The second part, Time Passes, takes place over ten years; it records the destruction of the house, the death of Mrs. Ramsay, the deaths of two of her children, and the coming of the First World War.", "بخش دوم، زمان می‌گذرد، در طول ده سال رخ می‌دهد؛ نابودی خانه را ثبت می‌کند، مرگ خانم رامزی، مرگ دو تن از بچه‌هایش و آمدن جنگ جهانی اول."),
            StoryParagraph("The third part, The Lighthouse, takes place on a single morning in 1920; it records the return of the survivors to the house, the completion of the journey to the Lighthouse, and the completion of Lily's painting.", "بخش سوم، فانوس دریایی، در صبحی واحد در ۱۹۲۰ رخ می‌دهد؛ بازگشت بازماندگان به خانه را ثبت می‌کند، کامل شدن سفر به فانوس دریایی و کامل شدن نقاشی لیلی."),
            StoryParagraph("The novel is not plot-driven; it is character-driven, and consciousness-driven, and image-driven.", "رمان طرح‌محور نیست؛ شخصیت‌محور است و آگاهی‌محور و تصویرمحور."),
            StoryParagraph("What matters is not what happens, but what is felt; not what is said, but what is thought; not what is seen, but what is understood.", "آنچه مهم است نه آنچه رخ می‌دهد، بلکه آنچه حس می‌شود؛ نه آنچه گفته می‌شود، بلکه آنچه فکر می‌شود؛ نه آنچه دیده می‌شود، بلکه آنچه فهمیده می‌شود."),
            StoryParagraph("At the center of the novel is Mrs. Ramsay, a woman of extraordinary beauty and extraordinary sympathy, who holds the family together by the force of her love.", "در مرکز رمان خانم رامزی است، زنی با زیبایی فوق‌العاده و همدلی فوق‌العاده، که خانواده را با نیروی عشقش کنار هم نگه می‌دارد."),
            StoryParagraph("Mrs. Ramsay is not perfect; she is proud, and she is manipulative, and she does not always understand her children.", "خانم رامزی بی‌عیب نیست؛ مغرور است و دستکاری‌گر و همیشه بچه‌هایش را نمی‌فهمد."),
            StoryParagraph("But she loves, and she loves deeply, and her love is the light that illuminates the entire novel.", "اما عشق می‌ورزد و عمیقاً عشق می‌ورزد و عشقش نوری است که تمام رمان را روشن می‌کند."),
            StoryParagraph("When she dies, in the second part, the novel seems to lose its center; the light goes out; the house falls into darkness.", "وقتی در بخش دوم می‌میرد، رمان به نظر مرکزش را از دست می‌دهد؛ نور خاموش می‌شود؛ خانه در تاریکی می‌افتد."),
            StoryParagraph("But the light does not go out entirely; it lives on in memory, in Lily's painting, in James's forgiveness, in the small moments that the survivors share.", "اما نور کاملاً خاموش نمی‌شود؛ در حافظه زندگی می‌کند، در نقاشی لیلی، در بخشش جیمز، در لحظه‌های کوچکی که بازماندگان قسمت می‌کنند."),
            StoryParagraph("This is one of the novel's deepest themes: that love does not end with death; that those we love live on within us, in ways that we cannot always see.", "این یکی از عمیق‌ترین مضامین رمان است: عشق با مرگ پایان نمی‌یابد؛ کسانی که دوستشان داریم درون ما زندگی می‌کنند، به شیوه‌هایی که همیشه نمی‌توانیم ببینیم."),
            StoryParagraph("Another theme is the passage of time, and the way that time both destroys and preserves.", "مضمون دیگر گذر زمان است و شیوه‌ای که زمان هم نابود می‌کند و هم حفظ."),
            StoryParagraph("Time destroys the house, and the family, and the world of 1910; but time also preserves the memory of what was, in the minds of those who lived it.", "زمان خانه را نابود می‌کند و خانواده را و جهان ۱۹۱۰ را؛ اما زمان خاطره آنچه بود را هم حفظ می‌کند، در ذهن کسانی که زندگی‌اش کردند."),
            StoryParagraph("And time heals, in its way, slowly, imperfectly; the survivors of the Ramsays come back to the house, ten years later, and they are able to laugh again, and to love again, and to live again.", "و زمان شفا می‌دهد، به شیوه خودش، آهسته، ناقص؛ بازماندگان رامزی‌ها ده سال بعد به خانه بازمی‌گردند و می‌توانند دوباره بخندند و دوباره عشق بورزند و دوباره زندگی کنند."),
            StoryParagraph("The third theme is art, and the relationship between art and life.", "مضمون سوم هنر است و رابطه میان هنر و زندگی."),
            StoryParagraph("Lily Briscoe is a painter; she spends the novel trying to paint a picture of Mrs. Ramsay and James, and she fails, and she fails again, and finally she succeeds.", "لیلی بریسکو نقاش است؛ رمان را صرف تلاش برای کشیدن تصویری از خانم رامزی و جیمز می‌کند و شکست می‌خورد و دوباره شکست می‌خورد و سرانجام موفق می‌شود."),
            StoryParagraph("What she learns is that art is not about reproducing reality; it is about capturing reality, about distilling reality, about finding the essential shape beneath the visible form.", "آنچه می‌آموزد این است که هنر درباره بازتولید واقعیت نیست؛ درباره ثبت واقعیت است، درباره تقطیر واقعیت، درباره یافتن شکل جوهری زیر فرم مرئی."),
            StoryParagraph("What she learns is that art is not about perfection; it is about honesty, about vision, about the willingness to see something as it truly is.", "آنچه می‌آموزد این است که هنر درباره کمال نیست؛ درباره صداقت است، درباره بینش، درباره آمادگی برای دیدن چیزی همانطور که واقعاً هست."),
            StoryParagraph("What she learns is that art, like love, is a way of holding on to what is passing; a way of making permanent what is fleeting; a way of saying yes to life.", "آنچه می‌آموزد این است که هنر، همچون عشق، شیوه‌ای است برای نگه داشتن آنچه می‌گذرد؛ شیوه‌ای برای ابدی کردن آنچه گذراست؛ شیوه‌ای برای بله گفتن به زندگی."),
            StoryParagraph("And this, perhaps, is the deepest meaning of the novel: that life is fleeting, and precious, and beautiful, and terrible, all at once; and that our task is to say yes to it.", "و این، شاید، عمیق‌ترین معنای رمان است: زندگی گذراست و گرانبها و زیبا و هولناک، همه با هم؛ و وظیفه ما بله گفتن به آن است."),
            StoryParagraph("To say yes to the summer day, and to the postponed trip, and to the dinner party.", "بله گفتن به روز تابستانی و به سفر به تعویق افتاده و به شام."),
            StoryParagraph("To say yes to the mother's love, and to the father's need, and to the children's anger.", "بله گفتن به عشق مادر و به نیاز پدر و به خشم بچه‌ها."),
            StoryParagraph("To say yes to the passing of time, and to the coming of death, and to the continuance of life.", "بله گفتن به گذر زمان و به آمدن مرگ و به ادامه زندگی."),
            StoryParagraph("To say yes to the painting, and to the vision, and to the light that shines across the darkness.", "بله گفتن به نقاشی و به بینش و به نوری که در تاریکی می‌تابد."),
            StoryParagraph("To say yes to the Lighthouse.", "بله گفتن به فانوس دریایی."),
            StoryParagraph("For the Lighthouse, in the end, is not just a building on a rock; it is the symbol of everything we reach for, and everything we love, and everything we hope to become.", "زیرا فانوس دریایی، در پایان، تنها ساختمانی روی صخره نیست؛ نماد هر چیزی است که به سمتش می‌رویم و هر چیزی که دوستش داریم و هر چیزی که امیدواریم بشویم."),
            StoryParagraph("It is the light that guides us home, across the dark water, through the long night, toward the dawn.", "نوری است که راه خانه را نشانمان می‌دهد، روی آب تاریک، در شب طولانی، به سمت سپیده‌دم."),
            StoryParagraph("And whether we reach it or not, the reaching is what matters; the reaching is the meaning; the reaching is the life.", "و خواه به آن برسیم یا نه، رسیدن است که اهمیت دارد؛ رسیدن معناست؛ رسیدن زندگی است."),
            StoryParagraph("To the Lighthouse is a novel of the ordinary and the eternal; of the small and the infinite; of the passing and the permanent.", "به سوی فانوس دریایی رمانی است از معمولی و ابدی؛ از کوچک و بی‌نهایت؛ از گذرا و پایدار."),
            StoryParagraph("It is a novel about a family, and about a house, and about a summer; and it is a novel about everyone, and about everywhere, and about every time.", "رمانی است درباره یک خانواده و درباره یک خانه و درباره یک تابستان؛ و رمانی است درباره همه و درباره همه‌جا و درباره هر زمان."),
            StoryParagraph("It is a novel that, once read, cannot be forgotten; that, once understood, changes the reader; that, once lived, becomes part of who we are.", "رمانی است که یک بار خوانده‌شده فراموش نمی‌شود؛ یک بار فهمیده‌شده خواننده را تغییر می‌دهد؛ یک بار زیسته‌شده بخشی از آنچه هستیم می‌شود."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For every reading is a new journey, toward the same Lighthouse, on the same sea, in the same light.", "زیرا هر خوانشی سفری نو است، به سمت همان فانوس دریایی، در همان دریا، در همان نور.")
        )
    )
}